/* Original implementation. Pixel cells form one non-overlapping planar partition. */
function createEngine(){
 const delta=(a,b)=>a.reduce((s,v,i)=>s+(v-b[i])**2,0);
 function lab(r,g,b){let q=[r,g,b].map(v=>{v/=255;return v>.04045?((v+.055)/1.055)**2.4:v/12.92});let x=(q[0]*.4124+q[1]*.3576+q[2]*.1805)/.95047,y=q[0]*.2126+q[1]*.7152+q[2]*.0722,z=(q[0]*.0193+q[1]*.1192+q[2]*.9505)/1.08883;[x,y,z]=[x,y,z].map(v=>v>.008856?Math.cbrt(v):7.787*v+16/116);return [116*y-16,500*(x-y),200*(y-z)];}
 function components(a,w,h){let ids=new Int32Array(a.length).fill(-1),rs=[],queue=new Int32Array(a.length);for(let p=0;p<a.length;p++){if(ids[p]>=0)continue;let id=rs.length,head=0,tail=1;queue[0]=p;ids[p]=id;let pixels=[];while(head<tail){let v=queue[head++];pixels.push(v);let x=v%w;for(let n of [x?v-1:-1,x<w-1?v+1:-1,v>=w?v-w:-1,v<a.length-w?v+w:-1])if(n>=0&&ids[n]<0&&a[n]===a[p]){ids[n]=id;queue[tail++]=n;}}rs.push({id,color:a[p],pixels});}return {ids,rs};}
 // Exact L-infinity distance to the nearest boundary pixel, conservatively measured.
 function measure(part,w,h,radius,minArea){let {ids,rs}=part,d=new Float32Array(ids.length).fill(1e6);for(let p=0;p<d.length;p++){let x=p%w,y=(p/w)|0;if(!x||!y||x===w-1||y===h-1||ids[p-1]!==ids[p]||ids[p+1]!==ids[p]||ids[p-w]!==ids[p]||ids[p+w]!==ids[p])d[p]=0;}
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){let p=y*w+x;for(let n of [x?p-1:-1,y?p-w:-1,x&&y?p-w-1:-1,x<w-1&&y?p-w+1:-1])if(n>=0)d[p]=Math.min(d[p],d[n]+1);}
 for(let y=h-1;y>=0;y--)for(let x=w-1;x>=0;x--){let p=y*w+x;for(let n of [x<w-1?p+1:-1,y<h-1?p+w:-1,x<w-1&&y<h-1?p+w+1:-1,x&&y<h-1?p+w-1:-1])if(n>=0)d[p]=Math.min(d[p],d[n]+1);}
 for(let r of rs){let p=r.pixels[0];for(let v of r.pixels)if(d[v]>d[p])p=v;r.anchor=p;r.radius=d[p];r.valid=d[p]>=radius&&r.pixels.length>=minArea;}return part;}
 function quantize(data,w,h,k,passes){let cache=new Map(),rgb=[],labs=[],idx=new Int32Array(w*h);for(let p=0;p<idx.length;p++){let o=p*4,alpha=data[o+3]/255,c=[0,1,2].map(i=>Math.round(data[o+i]*alpha+255*(1-alpha))),key=(c[0]<<16)|(c[1]<<8)|c[2];if(!cache.has(key)){cache.set(key,rgb.length);rgb.push(c);labs.push(lab(...c));}idx[p]=cache.get(key);}
 let samples=[];for(let p=0;p<idx.length;p+=Math.max(1,Math.floor(idx.length/10000)))samples.push(idx[p]);let centers=[labs[samples[0]]],mind=samples.map(()=>Infinity);for(let j=1;j<k;j++){let best=0;for(let i=0;i<samples.length;i++){mind[i]=Math.min(mind[i],delta(labs[samples[i]],centers[j-1]));if(mind[i]>mind[best])best=i;}if(mind[best]<.01)break;centers.push(labs[samples[best]]);}
 for(let t=0;t<12;t++){let sums=centers.map(()=>[0,0,0,0]);for(let s of samples){let c=0;for(let j=1;j<centers.length;j++)if(delta(labs[s],centers[j])<delta(labs[s],centers[c]))c=j;for(let j=0;j<3;j++)sums[c][j]+=labs[s][j];sums[c][3]++;}centers=centers.map((c,i)=>sums[i][3]?sums[i].slice(0,3).map(v=>v/sums[i][3]):c);}
 let lookup=labs.map(v=>{let c=0;for(let j=1;j<centers.length;j++)if(delta(v,centers[j])<delta(v,centers[c]))c=j;return c;}),a=Int32Array.from(idx,v=>lookup[v]),sums=centers.map(()=>[0,0,0,0]);for(let p=0;p<a.length;p++){let s=sums[a[p]],c=rgb[idx[p]];for(let j=0;j<3;j++)s[j]+=c[j];s[3]++;}let palette=sums.map(s=>s[3]?s.slice(0,3).map(v=>Math.round(v/s[3])):[255,255,255]);
 for(let t=0;t<passes;t++){let b=a.slice();for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let counts=new Int8Array(palette.length),p=y*w+x;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)counts[a[p+dy*w+dx]]++;let c=a[p];for(let j=0;j<counts.length;j++)if(counts[j]>=6)c=j;b[p]=c;}a=b;}return {a,palette};}
 function repair(a,palette,w,h,radius,minArea,locked=[],preserveDark=false){let merged=0,limit=false;let colors=palette.map(c=>lab(...c)),locks=new Set(locked);for(let pass=0;pass<32;pass++){let p=measure(components(a,w,h),w,h,radius,minArea),bad=p.rs.filter(r=>!r.valid&&!(preserveDark&&colors[r.color][0]<42)&&!r.pixels.some(v=>locks.has(v))).sort((a,b)=>a.pixels.length-b.pixels.length);if(!bad.length)return {...p,a,merged,limit};let changed=false,touched=new Set(),removed=new Set();for(let r of bad){if(touched.has(r.id))continue;let adj=new Map();for(let v of r.pixels){let x=v%w;for(let n of [x?v-1:-1,x<w-1?v+1:-1,v>=w?v-w:-1,v<a.length-w?v+w:-1])if(n>=0&&p.ids[n]!==r.id){let id=p.ids[n];adj.set(id,(adj.get(id)||0)+1);}}let best=-1,score=Infinity;for(let [id,border]of adj){if(removed.has(id))continue;let other=p.rs[id];let s=delta(colors[r.color],colors[other.color])/(1+Math.log1p(border)*.15);if(s<score){score=s;best=id;}}if(best>=0){for(let v of r.pixels)a[v]=p.rs[best].color;touched.add(r.id);touched.add(best);removed.add(r.id);merged++;changed=true;}}
 if(!changed)return {...measure(components(a,w,h),w,h,radius,minArea),a,merged,limit};if(pass===31)limit=true;}return {...measure(components(a,w,h),w,h,radius,minArea),a,merged,limit};}
 function split(part,w,h,radius,minArea,target){let next=part.rs.length,ids=part.ids.slice(),colors=part.rs.map(r=>r.color),queue=part.rs.slice();for(let r of queue){if(r.pixels.length<target*1.7||queue.length>2500)continue;let xmin=w,xmax=0,ymin=h,ymax=0;for(let v of r.pixels){let x=v%w,y=(v/w)|0;xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y);}let vertical=xmax-xmin>=ymax-ymin,cut=vertical?(xmin+xmax)/2:(ymin+ymax)/2;let trial=new Int32Array(w*h).fill(-1);for(let v of r.pixels)trial[v]=(vertical?v%w:(v/w)|0)<=cut?0:1;let c=measure(components(trial,w,h),w,h,radius,minArea).rs.filter(r=>r.color!==-1);if(c.length<2||c.some(r=>!r.valid))continue;for(let child of c){let id=next++;colors[id]=r.color;for(let v of child.pixels)ids[v]=id;queue.push({...child,id,color:r.color});}}
 let p=measure(components(ids,w,h),w,h,radius,minArea);for(let r of p.rs)r.color=colors[r.color];return p;}
 function run(input){let {data,w,h,options:o}=input,mm=o.widthMM/w,radius=(o.fontPt*25.4/72*.62+o.marginMM)/mm,minArea=o.minAreaMM/(mm*mm);let q=input.a?{a:Int32Array.from(input.a),palette:input.palette}:quantize(data,w,h,o.colors,o.noise);let repaired=repair(q.a,q.palette,w,h,radius,minArea,input.locked||[],o.preserveDark),p=o.cellMM>0?split(repaired,w,h,radius,minArea,(o.cellMM/mm)**2):repaired;for(let r of p.rs){if(!r.valid&&o.preserveDark&&lab(...q.palette[r.color])[0]<42){r.ink=true;r.valid=true;}}return {w,h,ids:p.ids,regions:p.rs.map(({pixels,...r})=>({...r,area:pixels.length})),a:q.a,palette:q.palette,merged:repaired.merged,limit:repaired.limit,options:o,invalid:p.rs.filter(r=>!r.valid).length};}
 return {run,components,measure,repair,split,quantize};
}
if(typeof module!=='undefined')module.exports=createEngine();
